linked_list_t *my_params_to_list(int ac, char * const *av)
{
    int i = 0;
    linked_list_t *rev;
    linked_list_t *element;

    for (i = 0; i < ac; i++) {
        element = malloc(sizeof(*element));
        element->data = av[i];
        element->next = rev;
        rev = element;
    }
    return (rev);
}
